"Variable expressions must be resolved before comparison. "
f"({self} &gt; {other})"
)
if self.references:
self = self.resolve()
if other.references:
other = other.resolve()
return self.offset &gt; other.offset
def __le__(self, other) -&gt; bool:
"""Compares two expressions.
        Returns:
            True if self &lt;= other.
        """
cls = type(self)
if not isinstance(other, cls):
other = cls(other)
if self.variables() or other.variables():
raise ValueError(
"Variable expressions must be resolved before comparison. "
f"({self} &lt;= {other})"
)
if self.references:
self = self.resolve()
if other.references:
other = other.resolve()
return self.offset &lt;= other.offset
def __ge__(self, other) -&gt; bool:
"""Compares two expressions.
        Returns:
